#!/usr/bin/env python3
"""Build the static GitHub Pages site; repository links survive a later rename."""
import json
import os
import pathlib
import re
import shutil
import subprocess
from site_docs import render_documents

root = pathlib.Path(__file__).resolve().parent.parent
repository = os.environ.get('GITHUB_REPOSITORY')
if not repository:
    remote = subprocess.check_output(['git', '-C', str(root), 'remote', 'get-url', 'origin'], text=True).strip()
    match = re.fullmatch(r'(?:https://github\.com/|git@github\.com:)([\w.-]+/[\w.-]+?)(?:\.git)?', remote)
    if not match:
        raise SystemExit('Set GITHUB_REPOSITORY to owner/repository for Pages links.')
    repository = match.group(1)
if not re.fullmatch(r'[\w.-]+/[\w.-]+', repository):
    raise SystemExit('Invalid GITHUB_REPOSITORY.')
source = root / 'docs/site'
destination = root / 'build/site'
for screenshot in ['network-settings-light.png', 'network-settings-dark.png', 'email-settings-light.png', 'email-settings-dark.png', 'smtp-credentials-light.png', 'smtp-credentials-dark.png', 'patch-special-recovery-light.png', 'patch-special-recovery-dark.png', 'patch-recovery-light.png', 'patch-recovery-dark.png', 'settings-layout-merge-colors-dark.png', 'settings-layout-merge-colors-light.png', 'settings-layout-small-bottom-dark.png', 'settings-layout-small-bottom-light.png', 'settings-layout-small-top-dark.png', 'settings-layout-small-top-light.png', 'settings-blame-colors-dark.png', 'settings-blame-colors-light.png', 'settings-colors-1-dark.png', 'settings-colors-1-light.png', 'settings-colors-2-dark.png', 'settings-colors-2-light.png', 'settings-colors-3-dark.png', 'settings-colors-3-light.png', 'settings-unified-colors-dark.png', 'settings-unified-colors-light.png', 'primary-commit-header-light.png', 'primary-commit-header-dark.png', 'primary-log-live-dates-light.png', 'primary-log-live-dates-dark.png', 'log-message-light.png', 'log-message-dark.png', 'add-list-light.png', 'add-list-dark.png', 'first-start-user-light.png', 'first-start-user-dark.png', 'first-start-authentication-light.png', 'first-start-authentication-dark.png', 'notes-message-styles-light.png', 'notes-message-styles-dark.png', 'image-toolbar-comparison-light.png', 'image-toolbar-comparison-dark.png', 'image-toolbar-selection-light.png', 'image-toolbar-selection-dark.png', 'status-text-commit-dark.png', 'status-text-commit-light.png', 'status-text-custom-commit-dark.png', 'status-text-custom-log-dark.png', 'status-text-custom-working-tree-dark.png', 'status-text-log-dark.png', 'status-text-log-light.png', 'status-text-working-tree-dark.png', 'status-text-working-tree-light.png', 'log-scope-information-light.png', 'log-scope-information-dark.png', 'log-native-filters-light.png', 'log-native-filters-dark.png', 'compare-native-toolbar-light.png', 'compare-native-toolbar-dark.png', 'merge-native-toolbar-light.png', 'merge-native-toolbar-dark.png', 'conflict-identities-text-light.png', 'conflict-identities-text-dark.png', 'conflict-identities-delete-light.png', 'conflict-identities-delete-dark.png', 'conflict-identities-rebase-light.png', 'conflict-identities-rebase-dark.png', 'partial-staging-current-light.png', 'partial-staging-current-dark.png', 'commit-current-light.png', 'commit-current-dark.png', 'staging-current-light.png', 'staging-current-dark.png', 'log-current-light.png', 'log-current-dark.png', 'working-tree-current-light.png', 'working-tree-current-dark.png', 'git-authentication-light.png', 'git-authentication-dark.png', 'blame-embedded-light.png', 'blame-embedded-dark.png', 'finder-watches-light.png', 'finder-watches-dark.png', 'browser-table-light.png', 'browser-table-dark.png', 'blame-wrap-light.png', 'blame-wrap-dark.png', 'blame-lexilla-light.png', 'blame-lexilla-dark.png', 'blame-source-editor-light.png', 'blame-source-editor-dark.png', 'hook-settings-light.png', 'hook-settings-dark.png', 'hook-config-light.png', 'hook-config-dark.png', 'autotext-tester-light.png', 'autotext-tester-dark.png', 'issue-tracker-config-light.png', 'issue-tracker-config-dark.png', 'issue-regex-tester-light.png', 'issue-regex-tester-dark.png', 'merge-whitespace-shapes-light.png','merge-whitespace-shapes-dark.png','merge-whitespace-icons-light.png','merge-whitespace-icons-dark.png', 'merge-line-diff-light.png', 'merge-line-diff-dark.png', 'merge-locator-light.png', 'merge-locator-dark.png', 'git-synchronization-light.png', 'git-synchronization-dark.png', 'sync-find-light.png', 'sync-find-dark.png', 'sync-export-light.png', 'sync-export-dark.png', 'merge-abort-options-light.png', 'merge-abort-options-dark.png', 'merge-abort-reset-failed-light.png', 'merge-abort-reset-failed-dark.png', 'log-ordering-light.png', 'log-ordering-dark.png', 'commit-containing-refs-light.png', 'commit-containing-refs-dark.png', 'revision-graph-light.png', 'revision-graph-dark.png', 'revision-graph-filter-light.png', 'revision-graph-filter-dark.png', 'image-open-light.png', 'image-open-dark.png', 'image-colors-light.png', 'image-colors-dark.png', 'image-frames-light.png', 'image-frames-dark.png', 'image-conflict-light.png', 'image-conflict-dark.png', 'unified-diff-viewer-light.png', 'repository-browser.png', 'text-merge.png', 'text-merge-dark.png', 'log-messages.png', 'working-tree-groups-light.png', 'working-tree-groups-dark.png', 'status.png', 'commit.png', 'commit-merge.png', 'commit-issue.png', 'commit-issue-dark.png', 'commit-issue-links.png', 'commit-issue-links-dark.png', 'commit-message-urls.png', 'commit-message-format.png', 'commit-message-format-dark.png', 'commit-completion.png', 'commit-completion-dark.png', 'commit-snippets.png', 'commit-snippets-popup.png', 'commit-snippets-dark.png', 'staging.png', 'partial-staging.png', 'switch-checkout.png', 'create-branch.png', 'create-tag.png', 'push.png', 'fetch.png', 'pull.png', 'rebase.png', 'rebase-dark.png', 'commit-light.png', 'commit-dark.png', 'commit-controls.png', 'commit-amend.png', 'commit-view-patch.png', 'commit-author-date.png', 'commit-resize.png', 'commit-history.png', 'commit-file-selection.png', 'commit-restore.png', 'revert.png', 'revert-dark.png', 'revert-progress.png', 'submodule-add-inputs-light.png', 'submodule-add-inputs-dark.png', 'submodule-update.png', 'submodule-update-result.png', 'submodule-update-dark.png', 'submodule-diff.png', 'changed-files.png', 'submodule-diff-dark.png', 'changed-files-dark.png', 'two-file-diff-dark.png', 'two-file-edit-dark.png', 'two-file-marked-dark.png', 'two-file-inline-dark.png', 'two-file-inline-light.png', 'blame-dark.png', 'blame-light.png', 'blame-highlight-light.png', 'blame-modes-light.png', 'blame-settings.png', 'blame-presentation-settings.png', 'blame-font-tabs-light.png', 'blame-log-settings.png', 'blame-locator-light.png', 'blame-locator-dark.png', 'blame-navigation-light.png', 'blame-graph-focus-light.png', 'blame-multiple-selection-light.png', 'blame-go-to-line.png', 'blame-find-light.png', 'alternative-editor.png', 'commit-add.png', 'commit-clipboard.png', 'commit-changelist.png', 'commit-groups-light.png', 'commit-groups-dark.png', 'commit-unversioned-preview.png', 'commit-file-pair.png', 'commit-checkbox-selection.png', 'commit-index-flags.png', 'merge.png', 'stash-save.png', 'stash-pop.png', 'lfs-locks-light.png', 'lfs-locks-dark.png', 'reflog.png', 'clone.png', 'create-repository.png', 'rename.png', 'ignore.png']:
    path = source / 'assets' / screenshot
    if not path.is_file() or path.read_bytes()[:8] != b'\x89PNG\r\n\x1a\n':
        raise SystemExit(f'Missing native screenshot: {path}')
shutil.copytree(source, destination, dirs_exist_ok=True)
manifest = json.loads((root / 'docs/upstream.json').read_text())
index = (destination / 'index.html').read_text()
for token, value in {'REPOSITORY_URL': 'https://github.com/' + repository,
                     'FILE_COUNT': f"{manifest['tracked_entries']:,}",
                     'DIALOG_COUNT': str(manifest['dialog_resources'])}.items():
    index = index.replace('@@' + token + '@@', value)
if '@@' in index:
    raise SystemExit('Unresolved website token.')
(destination / 'index.html').write_text(index)
report = render_documents(root, destination, repository)
print(json.dumps(report, indent=2))
(destination / '.nojekyll').touch()
print(destination)
